function editorUnits(text){const n=editorLocaleIndex();if(n===undefined)return text;return text.replace(/(\d+(?:~\d+)?)행/g,(_,v)=>[(v.includes('~')?'Rows ':'Row ')+v,v+'行',v+'行'][n]).replace(/(\d+(?:[.~]\d+)?)줄/g,(_,v)=>[v+' rows',v+'行',v+'行'][n]).replace(/(\d+(?:[.~]\d+)?)칸/g,(_,v)=>[v+' cells',v+'マス',v+'格'][n]).replace(/(\d+)회/g,(_,v)=>[v+(v==='1'?' time':' times'),v+'回',v+'次'][n]).replace(/(\d+)개/g,(_,v)=>[v+' items',v+'個',v+'个'][n]);}
